/* Home-health-only report support; no hospice payloads or scoring rules. */
function homehealthEdgeTables(){
 const c=current,o=c.options,edges=c.edges,ids=edges.map((e,i)=>'E'+String(i+1).padStart(6,'0'));
 const edgeRows=[['edge_id','source_feature_id','target_feature_id','feature_a','feature_b','method','score','shared_units','unit','context','year','text_scope','survey_component','severity_subset','node_color','wording_resolution','show_families'],...edges.map((e,i)=>[ids[i],e.source,e.target,features[e.source].label,features[e.target].label,o.method,e.weight,e.shared,unitName(),contextLabel(c.context),o.year,o.scope,o.modifier==='all'?'all':HHA.modifier_keys[Number(o.modifier)],o.severity,o.color,o.resolution,o.families])];
 const reports=[['source_excel_row','CCN','survey_date','survey_year','survey_context','survey_type_original','condition_level','screen_family_count','survey_group_index','supported_edge_ids','matched_feature_ids','matched_features','support_type','source_workbook_sha256']];
 const adjacency=new Map();for(const [i,e]of edges.entries())for(const id of [e.source,e.target]){if(!adjacency.has(id))adjacency.set(id,[]);adjacency.get(id).push(i);}
 for(const r of c.rows){
  const found=new Set(featurePairs(r,o.scope).map(p=>p[0]));if(o.families)for(const family of r[8])found.add(wordCount+family);
  const candidates=new Set(),support=[];for(const id of found)for(const i of adjacency.get(id)||[])candidates.add(i);
  for(const i of candidates){const e=edges[i];if(o.method==='incidence'?c.providers[e.source].has(r[1])&&c.providers[e.target].has(r[1]):found.has(e.source)&&found.has(e.target))support.push(i);}
  if(!support.length)continue;support.sort((a,b)=>a-b);const matched=[...found].filter(id=>adjacency.has(id)).sort((a,b)=>a-b);
  reports.push([r[0],String(HHA.CCNs[r[1]]),HHA_SURVEY_DATES[r[0]]||'',r[2],HHA.contexts[r[3]],HHA.survey_types[r[12]],r[4]?'Condition':'Other source hierarchy',r[8].length,r[9],support.map(i=>ids[i]).join(';'),matched.join(';'),matched.map(i=>features[i].label).join(';'),o.method==='incidence'?'Same source CCN; endpoint topics may occur in different records or years':'Both topics in the same workbook record',HHA.source_sha256]);
 }
 const settings=[['setting','value'],['exported_utc',new Date().toISOString()],['study','Home health only'],['version',HHA.version],['source_workbook_sha256',HHA.source_sha256],['edge_count',edges.length],['supporting_records',reports.length-1],['filters',JSON.stringify({...o,effective_context:contextLabel(c.context),comparison_side:comparison})],['join_key','Match each semicolon-separated supported_edge_ids value in CCN and year to edge_id in Edges. One record can support several edges.'],['CCN','Source CCNs are stored as text to preserve leading zeros. They are not registry-verified agency histories.'],['support_unit','Source workbook records, not verified patient events or independent report files. Survey-group indices refer to the existing derived CCN/event/date grouping.'],['text_rules','Care-issue flags always use evidence suffixes. Exact full-text collapse is within CCN and within the current filtered selection.'],['incidence_support','Both endpoints occur under the same CCN in the selected data, potentially in different reports/dates. The supporting sheet includes the relevant endpoint records.']];
 return [{name:'Edges',rows:edgeRows},{name:'CCN and year',rows:reports},{name:'Export settings',rows:settings}];
}
const homehealthCsvExport=$('exportEdges').onclick;
const homehealthCsvButton=hhaEl('button','btn','Edges CSV');homehealthCsvButton.id='exportEdgesCsv';homehealthCsvButton.type='button';homehealthCsvButton.onclick=homehealthCsvExport;$('exportEdges').after(homehealthCsvButton);
$('exportEdges').title='Excel workbook with edges, supporting CCNs and survey years';
$('exportEdges').onclick=async()=>{const b=$('exportEdges'),label=b.textContent;b.disabled=true;b.textContent='Preparing workbook…';try{await new Promise(resolve=>setTimeout(resolve,0));const blob=await edgeWorkbook(homehealthEdgeTables()),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='homehealth_network_edges_and_CCNs.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){alert('Export could not be completed. '+e.message);}finally{b.disabled=false;b.textContent=label;}};
