  const legend=make('div','pm-section-legend');legend.setAttribute('aria-label','Regulations shown in the sunburst');
  for(const b of branches){const key=button('',()=>pin({kind:'section',section:b.section},['§ '+b.section,titles[b.section],b.issues.length+' mapped issues','Select an outer issue for policy links and source evidence']),'pm-section-key');key.dataset.section=b.section;key.style.setProperty('--section-color',color(b.section));const swatch=make('span','pm-section-swatch');swatch.setAttribute('aria-hidden','true');const text=make('span');text.append(make('strong','','§ '+b.section),make('span','',titles[b.section]));key.append(swatch,text,make('span','pm-key-count',String(b.issues.length)));key.setAttribute('aria-label','Lock highlight for § '+b.section+' · '+titles[b.section]+' · '+b.issues.length+' mapped issues');legend.append(key);}host.append(legend);
