 const layout=make('div','pm-layout'),panel=make('section','pm-panel'),heading=make('div','pm-panel-head'),title=make('h2','','42 CFR Part 484 — Home Health Services');title.append(link('eCFR','https://www.ecfr.gov/current/title-42/chapter-IV/subchapter-G/part-484','pm-cfr-link'));heading.append(title);
